PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE categories(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL COLLATE NOCASE UNIQUE,icon TEXT NOT NULL DEFAULT 'tag',color TEXT NOT NULL DEFAULT '#64748b',enabled INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE payment_methods(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL COLLATE NOCASE UNIQUE,enabled INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE accounts(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL COLLATE NOCASE UNIQUE,enabled INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE transactions(id INTEGER PRIMARY KEY AUTOINCREMENT,amount_paise INTEGER NOT NULL CHECK(amount_paise>0),description TEXT NOT NULL,category_id INTEGER NOT NULL REFERENCES categories(id),payment_method_id INTEGER NOT NULL REFERENCES payment_methods(id),account_id INTEGER REFERENCES accounts(id),transaction_date TEXT NOT NULL,notes TEXT NOT NULL DEFAULT '',raw_input TEXT NOT NULL DEFAULT '',source TEXT NOT NULL DEFAULT 'manual',ai_confidence REAL,ai_model TEXT,ai_processed INTEGER NOT NULL DEFAULT 0,fingerprint TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE settings(key TEXT PRIMARY KEY,value TEXT NOT NULL,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE schema_version(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE favorites(id INTEGER PRIMARY KEY AUTOINCREMENT,description TEXT NOT NULL,category_id INTEGER REFERENCES categories(id),payment_method_id INTEGER REFERENCES payment_methods(id),account_id INTEGER REFERENCES accounts(id),amount_paise INTEGER,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE categorization_rules(id INTEGER PRIMARY KEY AUTOINCREMENT,keyword TEXT NOT NULL,merchant TEXT NOT NULL DEFAULT '',category_id INTEGER NOT NULL REFERENCES categories(id),priority INTEGER NOT NULL DEFAULT 100,enabled INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE recurring_expenses(id INTEGER PRIMARY KEY AUTOINCREMENT,description TEXT NOT NULL,amount_paise INTEGER NOT NULL,category_id INTEGER NOT NULL REFERENCES categories(id),payment_method_id INTEGER NOT NULL REFERENCES payment_methods(id),account_id INTEGER REFERENCES accounts(id),frequency TEXT NOT NULL,anchor_day INTEGER,next_date TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,last_generated_date TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE pending_entries(id INTEGER PRIMARY KEY AUTOINCREMENT,status TEXT NOT NULL,raw_input TEXT NOT NULL DEFAULT '',payload_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE income_entries(id INTEGER PRIMARY KEY AUTOINCREMENT,amount_paise INTEGER NOT NULL CHECK(amount_paise>0),source TEXT NOT NULL,account_id INTEGER REFERENCES accounts(id),income_date TEXT NOT NULL,notes TEXT NOT NULL DEFAULT '',version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE monthly_budgets(month_key TEXT PRIMARY KEY,expected_income_paise INTEGER NOT NULL DEFAULT 0,spending_limit_paise INTEGER NOT NULL DEFAULT 0,savings_target_paise INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE category_budgets(month_key TEXT NOT NULL,category_id INTEGER NOT NULL REFERENCES categories(id),limit_paise INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(month_key,category_id));
CREATE TABLE IF NOT EXISTS "d1_migrations"(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_transactions_date ON transactions(transaction_date DESC);
CREATE INDEX idx_transactions_fingerprint ON transactions(fingerprint);
CREATE INDEX idx_income_date ON income_entries(income_date DESC);
CREATE INDEX idx_transactions_category ON transactions(category_id);
CREATE INDEX idx_transactions_payment ON transactions(payment_method_id);
CREATE INDEX idx_transactions_account ON transactions(account_id);
CREATE INDEX idx_transactions_date_category ON transactions(transaction_date, category_id);
CREATE INDEX idx_transactions_date_payment ON transactions(transaction_date, payment_method_id);
CREATE INDEX idx_transactions_date_account ON transactions(transaction_date, account_id);
CREATE INDEX idx_recurring_due ON recurring_expenses(enabled, next_date);
